  public struct Theme: Sendable, Equatable {
    public let id: String
    public let light: Palette
    public let dark: Palette
    public let backdrop: Backdrop?
    public let glow: Glow?

    init(id: String, light: Palette, dark: Palette, backdrop: Backdrop?, glow: Glow?) {
      self.id = id
      self.light = light
      self.dark = dark
      self.backdrop = backdrop
      self.glow = glow
    }

    /// The theme with the id the `theme` editor setting stores, if there is one.
    public init?(_ id: String) {
      guard let theme = Theme.all.first(where: { $0.id == id }) else { return nil }
      self = theme
    }

    /// The theme `Tokens.Color` draws in; SwiftUI views that read a colour follow it.
    @MainActor public static var current: Theme {
      get { ThemeState.shared.theme }
      set { ThemeState.shared.theme = newValue }
    }

    /// Drawn in the theme of the window it shows in (`ThemeTrait`), so a colour set before a theme
    /// change takes the new theme; out of a window, in this theme.
    public func color(_ name: ColorName) -> UIColor {
      let fallback = self
      return UIColor(dynamicProvider: { traits in
        let theme = traits[ThemeTrait.self] ?? fallback
        return (traits.userInterfaceStyle == .dark ? theme.dark : theme.light).rgba(name).uiColor
      })
    }

    public static let `default`: Theme = Theme(id: "default", light: .defaultLight, dark: .defaultDark, backdrop: nil, glow: nil)
    public static let ivory: Theme = Theme(id: "ivory", light: .ivoryLight, dark: .ivoryDark, backdrop: nil, glow: Glow(light: [RGBA(0xefe6d2, 0.6), RGBA(0xece3cf, 0.5)], dark: [RGBA(0x3d3830, 0.6), RGBA(0x3a352c, 0.5)]))
